select count(*) as n, md5(string_agg(h, '' order by h)) as h from (select md5(concat_ws(chr(31), "path", "title", "kind", "module", "format", "artifact_url", "docs_id", "tab_name", "rev", "content", "pdf_path", "sha256")) h from public.documents where "path" in ('modules/F1-histories-of-making/docs/08-scope-v2/index.md', 'modules/F1-histories-of-making/docs/09-round-2/01-round-2.md')) s;